"""Freeze the experiment before any new measurements; no GPU workload here."""
import csv
from .common import *

def main():
 assert not (OUT/'protocol_identity.json').exists(), 'No overwrite of premeasurement freeze'
 source=ROOT/'results/module9a_interference'
 profile=load(source/'profile_protocol.json');catalog=load(source/'catalog.json')
 counts={(r['model'],r['task']):json.loads(r['kernel_counts']) for r in csv.DictReader((source/'kernel_profile_summary.csv').open())}
 paths={r['model']+'__'+r['task']:{'model':r['model'],'task':r['task'],'standalone_ms':r['standalone_s0_ms'],'kernel_count':sum(counts[r['model'],r['task']])/len(counts[r['model'],r['task']]),'kernel_count_samples':counts[r['model'],r['task']],'role':r['role']} for r in catalog['paths']}
 # Two co-paths of the same model make I1 vs I2 identifiable. The third
 # co-path provides a second co-model and Specialist-target transfer control.
 groups=[(('whisper-small','asr'),[('qwen','asr'),('qwen','visual_qa')],[('qwen','lid'),('phi4mm','visual_qa')]),
         (('whisper-small','lid'),[('qwen','asr'),('qwen','visual_qa')],[('qwen','lid'),('phi4mm','visual_qa')]),
         (('qwen','visual_qa'),[('whisper-small','asr'),('whisper-small','lid')],[('whisper_turbo','asr'),('whisper_turbo','lid')])]
 entries=[]
 for q,cal,val in groups:
  assert set(cal).isdisjoint(val)
  for split,targets in [('CALIBRATION',cal),('VALIDATION',val)]:
   for p in targets:
    identity={'target':list(p),'co_path':list(q)};entries.append({**identity,'id':p[0]+'__'+p[1]+'__from__'+q[0]+'__'+q[1],'split':split,'identity_sha256':digest(identity),'repetitions':[1,2,3]})
 targets=sorted({tuple(e['target']) for e in entries});states={}
 def make(p,q):
  m,k=p;co=q[0] if q else None;co_tasks=[q[1]] if q else []
  workers={n:profile['registry'][n] for n in ([m,co] if co else [m])}
  warm=[{'worker':n,'item':profile['items'][task][i%3]} for n,task in ([p,q] if q else [p]) for i in range(6)]
  return {'protocol_family':'current_active_pair','model':m,'task':k,'co_model':co,'co_tasks':co_tasks,'worker_specs':workers,'target_worker':m,'target_items':profile['items'][k][:30],'co_items':{l:profile['items'][l][:30] for l in co_tasks},'warmup_sequence':warm,'warmup_count':len(warm),'co_backlog':8,'target_schedule_seconds':[7*i for i in range(30)],'measurement_seconds':210,'minimum_overlap_ratio':.9,'budget_mib':49140,'drain_timeout_seconds':600}
 for p in targets:states[p[0]+'__'+p[1]+'__none']=make(p,None)
 for e in entries:states[e['id']]=make(tuple(e['target']),tuple(e['co_path']))
 protocol={'frozen_at_utc':now(),'states':states,'process_repetitions':3,'GPU':profile['GPU'],'environment_variables':profile['environment'],'fixed_input_seed':profile['sample_seed'],'source_profile_protocol_sha256':sha(source/'profile_protocol.json'),'ground_truth':'mean pair worker-handler latency / mean matched unprofiled standalone worker-handler latency; no host queue latency','warmup':'six requests per worker: first three IDs repeated twice, target then co; identical standalone target warmup','co_load':'one pure co-task, continuous replacement backlog 8; no MPS; different independent workers/contexts','historical_measurement_reuse':False,'historical_reason':'9A2 mixed co-tasks and different warmup/backlog cannot identify pure co-path pressure under this protocol','kernel_count':'arithmetic mean of the three preserved offline traces; no profiler latency feature','anchor':'new matched unprofiled standalone mean for measured paths, frozen unprofiled catalog for remaining paths; original catalog unchanged','retries':0,'max_new_runs':3*(len(targets)+len(entries)),'no_feature_expansion':True}
 save('path_features.json',{'paths':paths,'capacity_factors':catalog['capacity_factors'],'source_catalog_sha256':sha(source/'catalog.json')})
 save('pair_split_manifest.json',{'frozen_at_utc':now(),'grouping':'full directional (target model, target task, co model, co task); repetitions stay together','target_disjoint_for_each_co_path':True,'entries':sorted(entries,key=lambda e:e['identity_sha256']),'selection':'mechanistic contrast: two Whisper co-tasks; two calibration and two unseen targets per co-path; Qwen VQA co-path is Specialist transfer control; all new identities, not outcome-selected','calibration_identities':6,'validation_identities':6})
 save('protocol_identity.json',protocol)
 rule={'frozen_at_utc':now(),'formula':'T_hat[p<-q] = T_standalone[p] + mean_kernel_count[p] * delta[q]','delta_path':'median over calibration target identities of (mean_pair_ms - mean_matched_standalone_ms) / mean_kernel_count[target]; aggregate all three process repetitions within identity first','delta_model':'median of the same calibration identity estimates pooled by co-model, not co-path and not target model','no_interference':'delta = 0','fitting_scope':'CALIBRATION pair identities only; no coefficients learned from validation','co_path_seen_target_unseen':True,'primary_metric':'MAE of slowdown mu (dimensionless), equal weight to each of six validation identities','secondary':['median AE','RMSE','Spearman','Kendall','ordering','latency MAE ms'],'bootstrap':'50000 pair-identity paired resamples, seed 91023; process repetitions never split; identity CI conditional on fitted calibration; process-block uncertainty sensitivity reported separately','comparison':'all three signed MAE differences, two-sided 95% paired bootstrap intervals; no percent threshold','selection':'Order I0, I1, I2 by ascending validation MAE (complexity breaks exact ties). A candidate is eligible only if its error-difference upper 95% confidence bound is <0 against EVERY simpler model. I0 always eligible. Select lowest-MAE eligible candidate. No tuning, extra features, additional identities or retries after results.','routing_extension':'sum distinct co-model busy probability * baseline-demand-weighted co-path pressure, no same-model tax; empirical g handles own replicas','multi_model_status':'unvalidated additive approximation; low confidence for 3+ busy models; no new multi-model GPU campaign in this first bounded version','9B':'after 9A selection, fixed-deployment bounded routing iteration only; no candidate ranking or native runtime changes','statistical_limit':'six validation identities with shared targets/co-paths; bootstrap is exploratory conditional evidence, not independent six co-models; no population-wide claim'}
 save('model_comparison_freeze.json',rule)
 protected=list(load(source/'artifact_hashes.json').values())+load(source/'protected_references.json')
 save('protected_references.json',protected)
 (OUT/'prior_art_and_model.md').write_text('''# Lightweight scheduling pressure model\n\nThe earlier Runtime Sharing Semantics Audit rules out Roomie spatial occupancy simulation for this independent-process, independent-CUDA-context, no-MPS runtime. All 21 offline profiles are preserved. Only target kernel counts are consumed. No occupancy, kernel duration, cache, frequency, target susceptibility or neural-network features enter this version.\n\niGniter Eq. (5) decomposes scheduling delay as kernel count times baseline plus extra scheduling delay; its original experiments use MPS and its round-robin discussion is a conjecture. This implementation borrows the decomposition, not iGniter spatial provisioning or a verified scheduler policy. Source: https://arxiv.org/html/2211.01713v1 (Sec. III-A, Eq. 5-6).\n\nProject temporal-sharing adaptation: T_hat[p<-q] = T_p + n_p delta_q. The coefficient belongs to the co-resident model-task path q. delta_q = median_p ((T_pair[p<-q] - T_p)/n_p), with calibration targets only. It is an empirical residual pressure proxy, not an isolated context-switch duration; CPU effects, clocks and temporal scheduling can contribute to the observed residual. No target-specific fitted tax is used. Each co-path has two calibration target paths and two disjoint validation target paths. No historical mixed-task measurements are relabeled as pure co-path data.\n\nModel-level tax pools calibration residuals by co-model; task-path-level tax pools by co-path. Negative estimates are preserved and reported, not silently refitted or clipped. Inference outputs are checked for positive service times. New matched standalone measurements supply the T_p anchor for measured target paths; other admitted paths retain the frozen unprofiled s0. The small profiling sample remains a kernel-count sampling limitation.\n\nOnly TASK-PATH / ROUTING-CONDITIONED EXTENSION wording is claimed. Shared target/co-paths limit bootstrap independence; validation is a finite-domain migration test. The routing busy-probability/additive extrapolation is not yet multi-model GPU ground truth.\n''')
 save('campaign_state.json',{'phase':'FROZEN_BEFORE_NEW_GPU_RUNS','planned_runs':protocol['max_new_runs'],'new_completed_runs':0})
 print(json.dumps({'frozen':True,'calibration':6,'validation':6,'standalone_paths':len(targets),'GPU_runs':protocol['max_new_runs']}))

if __name__=='__main__':main()
